const b = $input.first().json.body || {};
const name = typeof b.name === 'string' ? b.name.trim() : '';
const phone = typeof b.phone === 'string' ? b.phone.trim() : '';
const message = typeof b.message === 'string' ? b.message.trim() : '';
const errors = [];
if (!name || name.length > 120) errors.push('name is required and must be at most 120 characters');
if (!/^[+() .0-9-]+$/.test(phone) || phone.replace(/\D/g,'').length < 7 || phone.replace(/\D/g,'').length > 15) errors.push('phone must contain 7 to 15 digits');
if (!message || message.length > 2000) errors.push('message is required and must be at most 2000 characters');
return [{ json: { valid: errors.length===0, errors, staff_message: ['Callback request','Name: '+name,'Phone: '+phone,'Message: '+message].join('\n') } }];
